package main

func academicWorkflowSchemas() map[string]any {
	paper := objReq([]string{"paper_id", "abstract"}, prop("paper_id", strSchema()), prop("title", strSchema()), prop("authors", array(strSchema())), prop("abstract", nullableSchema(strSchema())), prop("year", intSchema()), prop("venue", strSchema()), prop("doi", strSchema()), prop("arxiv_id", strSchema()), prop("paper_url", strSchema()), prop("pdf_url", strSchema()), prop("source_version", strSchema()), prop("source_provider", strSchema()), prop("document_id", strSchema()))
	workflowPaper := objReq([]string{"paper", "is_seed", "is_important"}, prop("paper", refSchema("AcademicPaperRef")), prop("is_seed", boolSchema()), prop("is_important", boolSchema()), prop("seed_relation", strSchema()), prop("direction_relation", strSchema()), prop("key_contribution", strSchema()))
	input := objReq([]string{"user_instruction", "candidate_directions", "selected_directions", "papers"}, prop("user_instruction", strSchema()), prop("candidate_directions", array(strSchema())), prop("selected_directions", array(strSchema())), prop("papers", array(refSchema("AcademicWorkflowPaper"))))
	presenceDocument := obj(prop("dataset_id", strSchema()), prop("dataset_name", strSchema()), prop("document_id", strSchema()), prop("document_name", strSchema()), prop("source_provider", strSchema()), prop("source_version", strSchema()), prop("content_sha256", strSchema()))
	return map[string]any{
		"AcademicPresenceDocument": presenceDocument,
		"AcademicPresence":         obj(prop("work_id", strSchema()), prop("metadata_only", boolSchema()), prop("status", strSchema()), prop("current_dataset", array(refSchema("AcademicPresenceDocument"))), prop("other_datasets", array(refSchema("AcademicPresenceDocument"))), prop("importing", boolSchema()), prop("coverage_complete", boolSchema())),
		"AcademicDocumentState":    obj(prop("document_id", strSchema()), prop("kind", enumStringSchema("paper", "other", "unknown")), prop("status", strSchema()), prop("paper_id", strSchema()), prop("revision", int64Schema()), prop("manual", boolSchema()), prop("error", strSchema())),
		"AcademicDocumentStatus":   obj(prop("state", refSchema("AcademicDocumentState")), prop("paper", refSchema("AcademicPaperRef")), prop("is_important", boolSchema()), prop("source_provider", strSchema()), prop("source_version", strSchema()), prop("content_sha256", strSchema()), prop("processing_status", strSchema()), prop("processing_error", strSchema())),
		"AcademicImportCandidate":  obj(prop("url", strSchema()), prop("version", strSchema()), prop("source_provider", strSchema()), prop("source_type", strSchema()), prop("expected_mime", strSchema())),
		"AcademicImportItem":       obj(prop("work_id", strSchema()), prop("reference_ids", array(strSchema())), prop("candidate", refSchema("AcademicImportCandidate"))),
		"AcademicImportCreate":     objReq([]string{"target_dataset_id", "items"}, prop("entry_type", enumStringSchema("single_reference", "paper_references", "collection_references", "paper_link")), prop("target_dataset_id", strSchema()), prop("target_pid", strSchema()), prop("source_document_ids", array(strSchema())), prop("idempotency_key", strSchema()), prop("items", array(refSchema("AcademicImportItem")))),
		"AcademicPaperRef":         paper, "AcademicWorkflowPaper": workflowPaper, "AcademicReviewInput": input,
		"AcademicTaskLaunch":       objReq([]string{"kind", "request_key"}, prop("kind", enumStringSchema("expansion", "review", "reflection", "ppt")), prop("dataset_id", strSchema()), prop("request_key", strSchema()), prop("document_ids", array(strSchema())), prop("direction", strSchema()), prop("user_instruction", strSchema()), prop("expansion_id", strSchema()), prop("expansion_version", int64Schema()), prop("paper_ids", array(strSchema())), prop("reflection_first", boolSchema())),
		"AcademicDocumentIdentity": obj(prop("kind", enumStringSchema("paper", "other", "unknown")), prop("reidentify", boolSchema()), prop("paper", obj(prop("title", strSchema()), prop("authors", array(strSchema())), prop("year", intSchema()), prop("venue", strSchema()), prop("abstract", strSchema()), prop("doi", strSchema()), prop("arxiv_id", strSchema())))),
		"AcademicContentRead":      map[string]any{"oneOf": []any{objReq([]string{"expansion_id", "paper_id"}, prop("expansion_id", strSchema()), prop("paper_id", strSchema())), objReq([]string{"cursor"}, prop("cursor", strSchema()), prop("expansion_id", strSchema()))}},
		"AcademicContentResponse":  objReq([]string{"status", "paper", "content_level", "content_hash", "pages", "next_cursor", "warnings"}, prop("status", enumStringSchema("processing", "ready", "unavailable", "failed")), prop("paper", refSchema("AcademicPaperRef")), prop("content_level", enumStringSchema("none", "fulltext")), prop("content_hash", strSchema()), prop("parser_version", strSchema()), prop("source_kind", enumStringSchema("kb", "external", "legacy")), prop("source_version", strSchema()), prop("pages", array(objReq([]string{"page", "text"}, prop("page", intSchema()), prop("text", strSchema())))), prop("next_cursor", strSchema()), prop("warnings", array(strSchema()))),
		"AcademicExpansion":        objReq([]string{"id", "dataset_id", "conversation_id", "status", "version", "result"}, prop("id", strSchema()), prop("discovery_mode", enumStringSchema("external", "legacy_mock")), prop("dataset_id", strSchema()), prop("conversation_id", strSchema()), prop("title", strSchema()), prop("goal", strSchema()), prop("status", strSchema()), prop("version", int64Schema()), prop("result", refSchema("AcademicReviewInput")), prop("progress", obj()), prop("created_at", dateTimeSchema()), prop("updated_at", dateTimeSchema())),
	}
}

func academicWorkflowPaths() map[string]any {
	operation := func(summary string, params []map[string]any, body, result map[string]any) map[string]any {
		value := op(summary, params, body, response(200, summary, result))
		value["tags"] = []string{"AcademicWorkflows"}
		return value
	}
	body := func(name string) map[string]any { return jsonBody(refSchema(name), true) }
	datasetQuery := queryParams(param("query", "dataset_id", true, strSchema()))
	recordPath := queryParams(param("path", "expansion_id", true, strSchema()))
	return map[string]any{
		"/academic/document-states":                   map[string]any{"get": operation("Read document scholarly identity and current user's importance", queryParams(param("query", "dataset_id", true, strSchema()), param("query", "document_ids", false, strSchema())), nil, obj(prop("items", array(refSchema("AcademicDocumentStatus")))))},
		"/academic/documents/{document_id}/identity":  map[string]any{"patch": operation("Correct document identity or retry recognition", queryParams(param("path", "document_id", true, strSchema())), body("AcademicDocumentIdentity"), obj(prop("status", strSchema())))},
		"/academic/papers/{paper_id}/importance":      map[string]any{"put": operation("Set current user's personal importance", queryParams(param("path", "paper_id", true, strSchema())), jsonBody(objReq([]string{"is_important"}, prop("is_important", boolSchema())), true), obj(prop("is_important", boolSchema())))},
		"/academic/paper-selections:resolve":          map[string]any{"post": operation("Expand folders completely and resolve distinct confirmed papers", nil, jsonBody(objReq([]string{"dataset_id", "document_ids"}, prop("dataset_id", strSchema()), prop("document_ids", array(strSchema()))), true), obj(prop("papers", array(refSchema("AcademicWorkflowPaper"))), prop("invalid", array(obj(prop("document_id", strSchema()), prop("reason", strSchema()))))))},
		"/academic/workflow-launches":                 map[string]any{"post": operation("Idempotently start expansion or a separate downstream Chat", nil, body("AcademicTaskLaunch"), obj(prop("conversation_id", strSchema()), prop("expansion_id", strSchema()), prop("handoff_id", strSchema())))},
		"/academic/papers:search":                     map[string]any{"post": operation("Search external arXiv candidates and pin their versions to an owned expansion", nil, jsonBody(objReq([]string{"expansion_id", "query"}, prop("expansion_id", strSchema()), prop("query", strSchema()), prop("max_results", map[string]any{"type": "integer", "minimum": 1, "maximum": 20, "default": 10})), true), obj(prop("papers", array(refSchema("AcademicPaperRef"))), prop("source", strSchema()), prop("mock", boolSchema())))},
		"/academic/imports:preview":                   map[string]any{"post": operation("Preview reference or identifier import into the current collection", nil, jsonBody(objReq([]string{"target_dataset_id"}, prop("target_dataset_id", strSchema()), prop("identifier", strSchema()), prop("expansion_id", strSchema()), prop("work_ids", array(strSchema())), prop("works", array(obj())), prop("reference_ids", array(strSchema())), prop("source_document_ids", array(strSchema())), prop("resolve_external", boolSchema())), true), obj(prop("items", array(obj()))))},
		"/academic/imports":                           map[string]any{"post": operation("Queue version-aware paper link or reference imports", nil, body("AcademicImportCreate"), obj(prop("batch_id", strSchema()), prop("status", strSchema())))},
		"/academic/paper-contents:read":               map[string]any{"post": operation("Read real full text without importing; continue using cursor only", nil, body("AcademicContentRead"), refSchema("AcademicContentResponse"))},
		"/academic/paper-contents:retry":              map[string]any{"post": operation("Retry failed full text download and parsing", nil, jsonBody(objReq([]string{"expansion_id", "paper_id"}, prop("expansion_id", strSchema()), prop("paper_id", strSchema())), true), obj(prop("status", strSchema())))},
		"/academic/expansions":                        map[string]any{"get": operation("List current user's expansion records", datasetQuery, nil, obj(prop("items", array(refSchema("AcademicExpansion")))))},
		"/academic/expansions/{expansion_id}":         map[string]any{"get": operation("Read saved rounds, cumulative papers, content states and Chat availability", recordPath, nil, obj(prop("record", refSchema("AcademicExpansion")), prop("rounds", array(obj())), prop("contents", array(obj())), prop("presence", array(refSchema("AcademicPresence"))), prop("paper_importance", map[string]any{"type": "object", "additionalProperties": boolSchema()}), prop("handoffs", array(obj())), prop("chat_status", enumStringSchema("available", "trashed", "deleted")))), "delete": operation("Confirm deletion of results and trash/cancel the expansion Chat", recordPath, jsonBody(objReq([]string{"confirm"}, prop("confirm", boolSchema())), true), obj(prop("deleted", boolSchema())))},
		"/academic/demo-papers":                       map[string]any{"get": operation("Get explicitly mocked recommendations with real paper identities", nil, nil, obj(prop("mock", boolSchema()), prop("papers", array(refSchema("AcademicPaperRef"))), prop("warning", strSchema())))},
		"/academic/mock-handoffs/{handoff_id}:submit": map[string]any{"post": operation("Submit the frozen original request to the Mock adapter; PPT relay reads its saved reflection", queryParams(param("path", "handoff_id", true, strSchema())), jsonBody(obj(prop("reflection_markdown", strSchema())), true), obj(prop("mock", boolSchema()), prop("kind", strSchema()), prop("input", refSchema("AcademicReviewInput")), prop("papers", array(refSchema("AcademicPaperRef"))), prop("reflection_markdown", strSchema()), prop("feedback", strSchema())))},
		"/academic/chat-context":                      map[string]any{"get": operation("Read owned academic Chat progress and handoff navigation", queryParams(param("query", "conversation_id", true, strSchema())), nil, obj(prop("kind", strSchema()), prop("expansion_id", strSchema()), prop("dataset_id", strSchema()), prop("status", strSchema()), prop("version", int64Schema()), prop("next_conversation_id", strSchema()), prop("source_conversation_id", strSchema()), prop("ready_count", intSchema()), prop("paper_count", intSchema())))},
	}
}
